function splitArray(nums, k) {
  let left = Math.max(...nums);
  let right = nums.reduce((a, b) => a + b, 0);

  function canSplit(maxSum) {
    let pieces = 1;
    let curr = 0;
    for (const num of nums) {
      if (curr + num > maxSum) {
        pieces++;
        curr = num;
      } else {
        curr += num;
      }
    }
    return pieces <= k;
  }

  let ans = right;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (canSplit(mid)) {
      ans = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  return ans;
}

