def splitArray(nums, k):
    left = max(nums)
    right = sum(nums)
    def can_split(max_s):
        pieces, curr = 1, 0
        for n in nums:
            if curr + n > max_s:
                pieces += 1
                curr = n
            else:
                curr += n
        return pieces <= k
    ans = right
    while left <= right:
        mid = (left + right) // 2
        if can_split(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1
    return ans
